package com.peertutoring.ui;

import com.peertutoring.model.Student;
import com.peertutoring.model.Subject;
import com.peertutoring.service.TutorService;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.sql.SQLException;
import java.util.List;

public class OfferTutoringFrame extends JFrame {
    private final Student student; private final TutorService tutorService=new TutorService(); private final JComboBox<Subject> subjects=new JComboBox<>(); private final DefaultListModel<Subject> offeredModel=new DefaultListModel<>(); private final JList<Subject> offeredList=new JList<>(offeredModel); private final JButton offerButton=new JButton("Offer selected subject"); private final JButton stopButton=new JButton("Stop offering selected");
    public OfferTutoringFrame(Student student){ this.student=student; setTitle("PeerTutoringSystems | Offer Tutoring");setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);setSize(650,500);setLocationRelativeTo(null); JPanel root=new JPanel(new BorderLayout(12,12));root.setBorder(new EmptyBorder(24,28,24,28));root.setBackground(new Color(245,247,251)); JLabel title=new JLabel("Manage tutoring subjects");title.setFont(new Font("SansSerif",Font.BOLD,24)); JLabel subtitle=new JLabel("Choose subjects you can help other students with.");subtitle.setForeground(new Color(105,116,135));JPanel head=new JPanel();head.setOpaque(false);head.setLayout(new BoxLayout(head,BoxLayout.Y_AXIS));head.add(title);head.add(Box.createVerticalStrut(6));head.add(subtitle);root.add(head,BorderLayout.NORTH);
        JPanel center=new JPanel(new GridLayout(1,2,18,0));center.setOpaque(false);JPanel left=new JPanel(new BorderLayout(8,8));left.setBackground(Color.WHITE);left.setBorder(new EmptyBorder(14,14,14,14));left.add(new JLabel("Available subjects"),BorderLayout.NORTH);left.add(subjects,BorderLayout.CENTER);offerButton.setBackground(new Color(48,88,166));offerButton.setForeground(Color.WHITE);left.add(offerButton,BorderLayout.SOUTH);JPanel right=new JPanel(new BorderLayout(8,8));right.setBackground(Color.WHITE);right.setBorder(new EmptyBorder(14,14,14,14));right.add(new JLabel("Currently offering"),BorderLayout.NORTH);right.add(new JScrollPane(offeredList),BorderLayout.CENTER);right.add(stopButton,BorderLayout.SOUTH);center.add(left);center.add(right);root.add(center,BorderLayout.CENTER);setContentPane(root);
        offerButton.addActionListener(e->offer());stopButton.addActionListener(e->stop());load(); }
    private void load(){try{List<Subject> all=tutorService.getAllSubjects();List<Subject> mine=tutorService.getSubjectsForTutor(student.getStudentId());subjects.removeAllItems();offeredModel.clear();for(Subject s:all)if(mine.stream().noneMatch(m->m.getSubjectId()==s.getSubjectId()))subjects.addItem(s);for(Subject s:mine)offeredModel.addElement(s);offerButton.setEnabled(subjects.getItemCount()>0);stopButton.setEnabled(!offeredModel.isEmpty());}catch(SQLException ex){showDbError();}}
    private void offer(){Subject s=(Subject)subjects.getSelectedItem();if(s==null){JOptionPane.showMessageDialog(this,"No additional subjects are available.");return;}try{tutorService.offerTutoring(student.getStudentId(),s.getSubjectId());JOptionPane.showMessageDialog(this,"You are now offering "+s.getSubjectName()+".","Success",JOptionPane.INFORMATION_MESSAGE);load();}catch(SQLException ex){showDbError();}catch(IllegalArgumentException ex){JOptionPane.showMessageDialog(this,ex.getMessage(),"Unable to offer subject",JOptionPane.WARNING_MESSAGE);}}
    private void stop(){Subject s=offeredList.getSelectedValue();if(s==null){JOptionPane.showMessageDialog(this,"Select a subject from your offering list.");return;}int c=JOptionPane.showConfirmDialog(this,"Stop offering "+s.getSubjectName()+"?","Confirm",JOptionPane.YES_NO_OPTION);if(c!=JOptionPane.YES_OPTION)return;try{boolean ok=tutorService.stopOfferingTutoring(student.getStudentId(),s.getSubjectId());JOptionPane.showMessageDialog(this,ok?"Tutoring offer removed.":"No change was made.");load();}catch(SQLException ex){showDbError();}catch(IllegalArgumentException ex){JOptionPane.showMessageDialog(this,ex.getMessage(),"Unable to update",JOptionPane.WARNING_MESSAGE);}}
    private void showDbError(){JOptionPane.showMessageDialog(this,"Could not load or update subjects. Check the database connection.","Database error",JOptionPane.ERROR_MESSAGE);}
}
